/**
 * The tickets of the service-desk seed, as specs for the engine (05-servicedesk-engine.mjs). Everything people type is realistic Bahasa Indonesia.
 *
 * A spec: { id, svc (catalog service), by (requester), creator (who files it, when not the requester), loc (a key of d.ctx.loc), subject, desc, ans (form answers),
 *           prio, asset (regex over the asset register), to (who should hold it), steps[], and when: wd + at:[h,m] (working days back), or ago (minutes), or endAgo (the last step
 *           happened that many minutes ago), or use (share of the resolution target used now: 0.3 on track, 0.9 at risk, 1.4 overdue) }.
 * Step offsets (m) are minutes after the previous step, moved into working hours.
 */
import { WIB, DAY, HOUR, MIN } from "./05-servicedesk-time.mjs";

const NOW = Date.now();
/** yyyy-mm-dd of the WIB day `n` days from today. */
export const day = (n) => new Date(NOW + WIB + n * DAY).toISOString().slice(0, 10);
/** ISO instant (Z) of hh:mm WIB on the day `n` days from today. */
export const dt = (n, hh, mm = 0) => new Date(Math.floor((NOW + WIB) / DAY) * DAY - WIB + n * DAY + hh * HOUR + mm * MIN).toISOString().replace(/\.\d+Z$/, "Z");

// ---- step helpers
const S = (m, by) => ({ k: "start", m, by });
const N = (m, text, by) => ({ k: "note", m, text, by });
const R = (m, text, by) => ({ k: "reply", m, text, by });
const Q = (m, text, by) => ({ k: "ask", m, text, by });
const HOLD = (m, reason, by) => ({ k: "hold", m, reason, by });
const RESUME = (m, by) => ({ k: "resume", m, by });
const D = (m, note, code, by) => ({ k: "resolve", m, note, code, by });
const C = (m, score, comment, rm) => ({ k: "confirm", m, rate: score ? [score, comment ?? null, rm] : null });
const RATE = (m, score, comment) => ({ k: "rate", m, score, comment });
const REOPEN = (m, reason, by) => ({ k: "reopen", m, reason, by });
const CANCEL = (m, reason, by) => ({ k: "cancel", m, reason, by });
const PHOTO = (m, by, name, rgb) => ({ k: "photo", m, by, name, rgb });
const APP = (m, by, comment) => ({ k: "approve", m, by, comment });
const REJ = (m, by, comment) => ({ k: "reject", m, by, comment });
const ASSIGN = (m, to, by) => ({ k: "assign", m, to, by });
const WO = (m, o) => ({ k: "wo", m, ...o });
const WS = (m, o) => ({ k: "wstart", m, ...o });
const WT = (m, n, o) => ({ k: "wtick", m, n, ...o });
const WTIME = (m, min, note, o) => ({ k: "wtime", m, min, note, ...o });
const WC = (m, kind, desc, unit, qty, o) => ({ k: "wcost", m, kind, desc, unit, qty, ...o });
const WP = (m, item, qty, fallback, o) => ({ k: "wpart", m, item, qty, fallback, ...o });
const WPH = (m, stage, o) => ({ k: "wphoto", m, stage, ...o });
const WH = (m, reason, o) => ({ k: "whold", m, reason, ...o });
const WD = (m, note, o) => ({ k: "wdone", m, note, ...o });
const WX = (m, reason, o) => ({ k: "wcancel", m, reason, ...o });

// ---- parts and vendors (matched against what the stock and asset modules created; manual cost lines when there is no such item)
const LED = /lampu|led|tl\b|neon/i, FREON = /freon|r32|r410|refrigerant/i, KABEL = /kabel|cable/i, KRAN = /kran|faucet|fitting|pipa|stop ?kran|keran/i, FILTER = /filter/i, MCB = /mcb|breaker|sekring/i;
const HANDLE = /engsel|handle|kunci|lock|hinge|roda|caster/i, SOCKET = /stop ?kontak|socket|outlet|saklar|switch/i, BATT = /baterai|battery|aki/i, CLEAN = /pembersih|cairan|sabun|chemical|disinfect/i;
const V_AC = /sejuk/i, V_ELEC = /listrik|electric|elektrik|power/i, V_PEST = /hama|pest|fumig|anti ?rayap/i, V_BLDG = /bangunan|sipil|plumb|pipa|waterproof|konstruksi/i;
const A_AC = /\bAC\b|air ?con|split|pendingin|chiller/i, A_UPS = /ups|genset|panel/i, A_LIGHT = /lampu|light|emergency/i, A_CHAIR = /kursi|chair/i, A_PUMP = /pompa|pump/i;

// ---- answer helpers
const ac = (problem, stop = false) => ({ problem, disruptive: stop });
const el = (problem, unsafe = false) => ({ problem, unsafe });
const wt = (problem) => ({ problem });

/** Photos: the colour is just to tell them apart. */
const ph = (by, name, rgb) => PHOTO(8, by, name, rgb);

